#!/bin/sh
# Подставной источник расписания для сквозной проверки Python-пути.
#
# Нужен, чтобы проверить всю цепочку «страница -> сервер -> дочерний процесс ->
# база -> страница» без обращений к чужому API: живая проверка дело полезное, но
# в CI она либо упадёт без сети, либо выложит токен вуза в публичный раннер.
#
# Соблюдает договорённость fetch.py, а не свою:
#
#   * вызов `sh <этот файл> --groups`              -> каталог групп одной строкой;
#   * вызов `sh <этот файл> --group-id --month --year` -> пары за месяц;
#   * токен только окружением: в аргументах его быть не должно, и это здесь
#     проверяется, потому что в `ps` командная строка видна всем;
#   * код 2 — «парсер не запускается», код 1 — «данных нет».
#
# Вывод — JSON той же формы, что и у живого ответа после разбора: аудитория с
# HTML-разметкой, поток из двух групп, подгруппы «1 подгруппа» и «—».

case " $* " in
  *" $APEKS_TOKEN "*)
    echo "токен просочился в аргументы дочернего процесса" >&2
    exit 2
    ;;
esac

if [ -z "$APEKS_TOKEN" ]; then
  echo "APEKS_TOKEN пуст: мост обязан передавать доступ окружением" >&2
  exit 2
fi

if [ "$1" = "--groups" ]; then
  printf '%s' '{"groups":[{"id":"494","name":"Б-ИСиТ-22","department":"Инженерно-технологический институт","course":"2 курс"},{"id":"495","name":"Б-ИСиТ-23","department":"Инженерно-технологический институт","course":"2 курс"}]}'
  exit 0
fi

# Проверка договорённости об аргументах: мост обязан звать ровно --group-id,
# --month и --year. Расхождение здесь — первая же страница, которая перестала
# получать данные, поэтому она проверяется, а не предполагается.
if [ "$1" != "--group-id" ] || [ "$3" != "--month" ] || [ "$5" != "--year" ]; then
  echo "неожидаемые аргументы: $*" >&2
  exit 2
fi

group="$2"
month="$4"
year="$6"

if [ "$group" != "494" ] || [ "$month" != "10" ] || [ "$year" != "2026" ]; then
  # Месяц без пар — не ошибка: так выглядят каникулы, и страница обязана
  # показать «пар нет», а не «импорт не удался».
  printf '%s' "{\"group_id\":\"$group\",\"group_name\":\"Б-ИСиТ-22\",\"start_date\":\"01.10.2026\",\"end_date\":\"31.10.2026\",\"lessons\":[]}"
  exit 0
fi

printf '%s' '{"group_id":"494","group_name":"Б-ИСиТ-22","start_date":"01.10.2026","end_date":"31.10.2026","lessons":[{"external_id":"py:e9d3f9694abd2ac5","date":"02.10.2026","day":"Пт","lesson_number":3,"time":"12:20 – 13:55","group":"Б-ИСиТ-22, Б-ИСиТ-23","subgroup":"Поточка","discipline":"Элективные курсы по физической культуре и спорту","lesson_type":"Лек","room":"<i class=\"fa fa-times\"></i> без ауд.","teacher":"Малышко С. С."},{"external_id":"py:a5b9269a50c0af2b","date":"02.10.2026","day":"Пт","lesson_number":4,"time":"14:10 – 15:45","group":"Б-ИСиТ-22","subgroup":"—","discipline":"История России","lesson_type":"Лек","room":"к. 2/102","teacher":"Кузнецов А. В."},{"external_id":"py:bc0c7c0640ee1fd9","date":"05.10.2026","day":"Пн","lesson_number":1,"time":"08:30 – 10:05","group":"Б-ИСиТ-22","subgroup":"1 подгруппа","discipline":"Базы данных","lesson_type":"Лб","room":"к. 3/314","teacher":"Иванов И. И."}]}'
